-- Expanded school-to-university subject catalogue.
-- Generated from src/data/subjectCatalog.js. Existing subject IDs are retained.
create table public.subject_categories (
  slug text primary key check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name text not null unique check (length(btrim(name)) > 0),
  emoji text not null default '📚',
  sort_order integer not null default 0 check (sort_order >= 0),
  is_active boolean not null default true
);
create table public.education_levels (
  code text primary key check (code ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name text not null unique check (length(btrim(name)) > 0),
  min_grade smallint,
  max_grade smallint,
  sort_order integer not null default 0 check (sort_order >= 0),
  is_active boolean not null default true,
  constraint education_levels_grade_range check (
    (min_grade is null and max_grade is null) or
    (min_grade is not null and max_grade is not null and min_grade >= 0 and max_grade <= 12 and min_grade <= max_grade)
  )
);
alter table public.subjects
  add column aliases text[] not null default '{}',
  add column is_popular boolean not null default false,
  add column sort_order integer not null default 0 check (sort_order >= 0);
create table public.subject_education_levels (
  subject_id bigint not null references public.subjects(id) on delete cascade,
  level_code text not null references public.education_levels(code) on update cascade on delete restrict,
  primary key (subject_id, level_code)
);
create index subject_education_levels_level_idx on public.subject_education_levels (level_code, subject_id);
create index subjects_category_idx on public.subjects (category);

insert into public.subject_categories (slug, name, emoji, sort_order)
select slug, name, emoji, sort_order
from jsonb_to_recordset('[{"slug":"primary-foundations","name":"Primary Foundations","emoji":"🌱","sort_order":0},{"slug":"mathematics","name":"Mathematics","emoji":"📐","sort_order":1},{"slug":"natural-sciences","name":"Natural Sciences","emoji":"🔬","sort_order":2},{"slug":"languages","name":"Languages","emoji":"📚","sort_order":3},{"slug":"humanities-social-sciences","name":"Humanities & Social Sciences","emoji":"🌍","sort_order":4},{"slug":"technology-coding","name":"Technology & Coding","emoji":"💻","sort_order":5},{"slug":"business-economics","name":"Business & Economics","emoji":"📊","sort_order":6},{"slug":"engineering-built-environment","name":"Engineering & Built Environment","emoji":"⚙️","sort_order":7},{"slug":"health-medical-sciences","name":"Health & Medical Sciences","emoji":"🧬","sort_order":8},{"slug":"law-public-administration","name":"Law & Public Administration","emoji":"⚖️","sort_order":9},{"slug":"education-teaching","name":"Education & Teaching","emoji":"🎓","sort_order":10},{"slug":"agriculture-environment","name":"Agriculture & Environmental Studies","emoji":"🌿","sort_order":11},{"slug":"creative-arts-music","name":"Creative Arts & Music","emoji":"🎨","sort_order":12},{"slug":"vocational-technical","name":"Vocational & Technical Studies","emoji":"🛠️","sort_order":13},{"slug":"test-preparation","name":"Study Skills & Test Preparation","emoji":"🎯","sort_order":14},{"slug":"research-academic-skills","name":"Research & Academic Skills","emoji":"🔍","sort_order":15}]'::jsonb) as c(slug text, name text, emoji text, sort_order integer);
insert into public.education_levels (code, name, min_grade, max_grade, sort_order)
select code, name, min_grade, max_grade, sort_order
from jsonb_to_recordset('[{"code":"foundation","name":"Foundation · Grades R–3","min_grade":0,"max_grade":3,"sort_order":0},{"code":"intermediate","name":"Intermediate · Grades 4–6","min_grade":4,"max_grade":6,"sort_order":1},{"code":"senior","name":"Senior · Grades 7–9","min_grade":7,"max_grade":9,"sort_order":2},{"code":"fet","name":"High school · Grades 10–12","min_grade":10,"max_grade":12,"sort_order":3},{"code":"college","name":"College / TVET","min_grade":null,"max_grade":null,"sort_order":4},{"code":"undergraduate","name":"University · Undergraduate","min_grade":null,"max_grade":null,"sort_order":5},{"code":"postgraduate","name":"University · Postgraduate","min_grade":null,"max_grade":null,"sort_order":6},{"code":"adult","name":"Adult & continuing learning","min_grade":null,"max_grade":null,"sort_order":7}]'::jsonb) as l(code text, name text, min_grade smallint, max_grade smallint, sort_order integer);

